const fs=require('node:fs'),readline=require('node:readline');let n=0;const send=x=>process.stdout.write(JSON.stringify(x)+'\n');readline.createInterface({input:process.stdin}).on('line',line=>{const m=JSON.parse(line),p=m.params||{};if(!m.method)return;if(process.env.CHAT_SPEED_LOG)fs.appendFileSync(process.env.CHAT_SPEED_LOG,JSON.stringify({method:m.method,...(m.method==='thread/start'?{instructions:p.developerInstructions,tools:!!p.dynamicTools}:{}),...(m.method==='turn/start'?{effort:p.effort,text:p.input[0].text}: {})})+'\n');const reply=result=>send({id:m.id,result});switch(m.method){case 'initialize':reply({});break;case 'account/read':reply({account:{type:'chatgpt',planType:'fixture'}});break;case 'model/list':reply({data:[{model:'fixture-codex',displayName:'本地模拟',isDefault:true,supportedReasoningEfforts:[{reasoningEffort:'low'},{reasoningEffort:'high'}],defaultReasoningEffort:'high'}]});break;case 'thread/start':reply({thread:{id:'thread-'+(++n)}});break;case 'turn/start':{const id='turn-'+(++n),threadId=p.threadId;reply({turn:{id}});send({method:'turn/started',params:{threadId,turn:{id}}});send({method:'item/agentMessage/delta',params:{threadId,delta:'模拟回复'}});setTimeout(()=>{send({method:'item/completed',params:{threadId,item:{type:'agentMessage',phase:'final_answer',text:'模拟回复'}}});send({method:'turn/completed',params:{threadId,turn:{id,status:'completed'}}})},80);break}}});
